public int findLargestSubstring(List<String> strings) {
    // Initialize a variable to store the length of the longest substring
    int longestSubstringLength = 0;

    // Iterate over each string in the list
    for (String string : strings) {
        // Get the length of the string
        int stringLength = string.length();

        // Iterate over each substring of the string
        for (int i = 0; i < stringLength; i++) {
            // Get the length of the substring starting at index i
            int substringLength = stringLength - i;

            // Check if the substring is a palindrome
            if (isPalindrome(string.substring(i, substringLength))) {
                // If it is, update the length of the longest substring
                longestSubstringLength = Math.max(longestSubstringLength, substringLength);
            }
        }
    }

    // Return the length of the longest substring
    return longestSubstringLength;
}

