public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[][] dp = new int[n][2];

    // Initialize the base cases
    dp[0][0] = 0;
    dp[0][1] = 0;

    // Loop through the nodes in reverse order (bottom-up)
    for (int i = n - 1; i >= 0; i--) {
        // Loop through the edges connected to this node
        for (int j = 0; j < edges.length; j++) {
            if (edges[j][0] == i) {
                int destNode = edges[j][1];
                int timeToReachDestNode = dp[destNode][0];
                int timeToReachDestNodeViaCurrentNode = timeToReachDestNode + (hasApple[i] ? 1 : 0);
                dp[i][0] = Math.min(dp[i][1] + timeToReachDestNode, timeToReachDestNodeViaCurrentNode);
                dp[i][1] = dp[i][0] + (hasApple[i] ? 1 : 0);
            }
        }
    }

    return dp[0][0];
}

