        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = (2 * i) + 1;
        }

        // Initialize the count of operations to 0
        int count = 0;

        // Iterate until all elements in arr are equal
        while (!allEqual(arr)) {
            // Find the index of the maximum element in arr
            int maxIndex = maxIndex(arr);
            // Find the index of the minimum element in arr
            int minIndex = minIndex(arr);
            // Subtract 1 from the maximum element and add 1 to the minimum element
            arr[maxIndex] -= 1;
            arr[minIndex] += 1;
            // Increment the count of operations
            count++;
        }

        // Return the count of operations
        return count;
    }

