public String getSmallestString(int n, int k) {
    if (n < 0 || k < 0) {
        return "";
    }
    String result = "";
    while (n > 0) {
        int value = k % 26;
        char c = (char) ('a' + value - 1);
        result += c;
        k -= value;
        k /= 26;
        n--;
    }
    return result;
}

