return false;
}

int slope1 = (y1 - y2) / (x1 - x2);
int slope2 = (y2 - y3) / (x2 - x3);

if (slope1 * (x1 - x3) + y1 == slope2 * (x2 - x3) + y2) {
return false;
}

return true;
}

