    for (int i = 1; i <= n; i++) {
        String str = String.valueOf(i);
        int idx = 0;
        while (idx < result.size() && str.compareTo(String.valueOf(result.get(idx))) > 0) {
            idx++;
        }
        result.add(idx, i);
    }
    return result;
}

