public static int minPerfectSquareSum(int n) {
    // Initialize a list to store the perfect square numbers
    List<Integer> perfectSquares = new ArrayList<>();

    // Iterate from 1 to the square root of n
    for (int i = 1; i * i <= n; i++) {
        // If i is a perfect square, add it to the list
        if (i * i == n) {
            perfectSquares.add(i);
        }
    }

    // Initialize a variable to store the minimum number of perfect square numbers
    int minPerfectSquares = Integer.MAX_VALUE;

    // Iterate through the list of perfect square numbers
    for (int i = 0; i < perfectSquares.size(); i++) {
        // Get the current perfect square number
        int currentPerfectSquare = perfectSquares.get(i);

        // Initialize a variable to store the number of perfect square numbers needed to sum up to n
        int count = 1;

        // Iterate from the current perfect square number to n
        for (int j = currentPerfectSquare; j <= n; j += currentPerfectSquare) {
            // Increment the count if j is a perfect square number
            if (j * j == n) {
                count++;
            }
        }

        // Update the minimum number of perfect square numbers if necessary
        if (count < minPerfectSquares) {
            minPerfectSquares = count;
        }
    }

    // Return the minimum number of perfect square numbers
    return minPerfectSquares;
}

